def transform(grid):
    h, w = len(grid), len(grid[0])
    freq = {}
    for row in grid:
        for v in row:
            freq[v] = freq.get(v, 0) + 1
    rowbar = next((r for r in range(h) if len(set(grid[r])) == 1 and freq[grid[r][0]] == w), None)
    colbar = next((c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and freq[grid[0][c]] == h), None)
    if rowbar is not None:
        axis, barrier_pos, barrier_color = 0, rowbar, grid[rowbar][0]
    else:
        axis, barrier_pos, barrier_color = 1, colbar, grid[0][colbar]
    bg = max((v for v in freq if v != barrier_color), key=lambda v: freq[v])
    obj = {(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (bg, barrier_color)}
    if not obj:
        return [row[:] for row in grid]
    coords = [r if axis == 0 else c for r, c in obj]
    lo, hi = min(coords), max(coords)
    if barrier_pos < lo:
        delta = barrier_pos + 1 - lo
        # The stripe goes just beyond the object's far edge, away from the barrier.
        stripe_pos = hi + delta + 1
    else:
        delta = barrier_pos - 1 - hi
        stripe_pos = lo + delta - 1
    out = [[bg for _ in range(w)] for _ in range(h)]
    if axis == 0:
        out[barrier_pos] = grid[barrier_pos][:]
    else:
        for r in range(h):
            out[r][barrier_pos] = barrier_color
    for r, c in obj:
        rr, cc = (r + delta, c) if axis == 0 else (r, c + delta)
        out[rr][cc] = grid[r][c]
    if 0 <= stripe_pos < (h if axis == 0 else w):
        if axis == 0:
            out[stripe_pos] = [8] * w
        else:
            for r in range(h):
                out[r][stripe_pos] = 8
    return out
